import numpy as np
from scipy.optimize import fsolve

def count_solutions_for_z(z):
    # Fix z, solve for x, y
    def eqs(p):
        x, y = p
        return [x**2 + y**2 - (3 - z**2), x*y**3 + y*z**3 + z*x**3 - 3]

    sols = []
    # Try multiple starting points for x, y
    for x0 in np.linspace(-2, 2, 10):
        for y0 in np.linspace(-2, 2, 10):
            sol, info, ier, msg = fsolve(eqs, [x0, y0], full_output=True)
            if ier == 1:
                # Check if it's actually a solution
                x, y = sol
                if np.allclose(eqs([x, y]), 0, atol=1e-8):
                    # Normalize to avoid duplicates
                    sols.append(np.round(sol, 6))

    unique_sols = []
    for s in sols:
        if not any(np.allclose(s, us, atol=1e-4) for us in unique_sols):
            unique_sols.append(s)
    return unique_sols

all_sols = []
for z in np.linspace(-np.sqrt(3), np.sqrt(3), 200):
    sols_z = count_solutions_for_z(z)
    for s in sols_z:
        sol = np.append(s, z)
        if not any(np.allclose(sol, us, atol=1e-3) for us in all_sols):
            all_sols.append(sol)

print(f"Total solutions found: {len(all_sols)}")
for s in all_sols:
    print(s)

