import numpy as np
from scipy.optimize import minimize

def equations(p):
    x, y, z = p
    return (x**2 + y**2 + z**2 - 3)**2 + (x*y**3 + y*z**3 + z*x**3 - 3)**2

def find_solutions():
    solutions = []
    # Use more starts to be sure
    for _ in range(10000):
        v = np.random.uniform(-2, 2, 3)
        res = minimize(equations, v, method='BFGS', tol=1e-12)
        if res.fun < 1e-12:
            sol = np.round(res.x, 8)
            is_new = True
            for s in solutions:
                if np.allclose(s, sol, atol=1e-6):
                    is_new = False
                    break
            if is_new:
                solutions.append(sol)
    return solutions

sols = find_solutions()
print(f"Found {len(sols)} unique solutions:")
for s in sols:
    print(s)
